# frozen_string_literal: true

RSpec.describe "1000.menu" do
  subject(:recipe) { scrape_cassette("menu/1000", url: "https://1000.menu/cooking/41421-kabachkovye-oladi-iz-kabachkov-na-skovorode") }

  it "reads the title" do
    expect(recipe.title).to eq("Кабачковые оладьи из кабачков на сковороде")
  end

  it "reads every ingredient line" do
    expect(recipe.ingredients).to eq([
      "Кабачки - 500 гр",
      "Яйца - 1 шт.",
      "Пшеничная мука - 3 стол.л.",
      "Соль - по вкусу",
      "Растительное масло - 2 стол.л."
    ])
  end

  it "parses every ingredient line into an amount, a unit and an ingredient" do
    expect(recipe.parsed_ingredients.map(&:to_h)).to eq([
      { amount: 500.0, unit: "гр", name: "Кабачки" },
      { amount: 1.0, unit: "шт", name: "Яйца" },
      { amount: 3.0, unit: "стол.л", name: "Пшеничная мука" },
      { amount: nil, unit: nil, name: "Соль - по вкусу" },
      { amount: 2.0, unit: "стол.л", name: "Растительное масло" }
    ])
  end

  it "reads every instruction step" do
    expect(recipe.instructions_list).to eq([
      "Шаг 1. Как сделать кабачковые оладьи на сковороде?",
      "Подготовьте продукты. Кабачки вымойте.",
      "Замена ингредиентов",
      "Кабачки → цуккини, патиссоны, тыква (молодая)",
      "Пшеничная мука → цельнозерновая, овсяная, кукурузная, безглютеновая смесь",
      "Яйца → перепелиные (увеличить количество в 3 раза)",
      "Соль → морская, гималайская, травяная смесь",
      "Растительное масло → оливковое, подсолнечное рафинированное, масло авокадо",
      "Совет",
      "Для оладий выбирайте молодые кабачки с тонкой кожицей и мелкими семенами. Если используете старые кабачки, очистите их и удалите семена.",
      "Шаг 2. Как правильно подготовить кабачки?",
      "Натрите кабачок на крупной терке. Отожмите получившуюся массу. Сок слейте.",
      "Как выбрать универсальную тёрку?",
      "Ищите четырёхгранную тёрку из нержавеющей стали с удобной ручкой и резиновыми ножками. Обязательно наличие всех четырёх типов отверстий: крупные и мелкие капли (для сыра, овощей), пятиугольники (для цедры, имбиря) и продолговатые (для нарезки колечками). Чек-лист по выбору идеальной тёрки — в гиде Кулинарной Академии.",
      "Советы",
      "Посыпьте натёртые кабачки солью и оставьте на 10-15 минут, затем отожмите — соль вытянет максимум влаги, и оладьи будут особенно хрустящими и не разваливаться при жарке.",
      "Сбрызните натёртые кабачки лимонным соком перед отжимом — кислинка сохранит их цвет и добавит лёгкую свежую ноту.",
      "Диетические адаптации",
      "Мука → заменить на цельнозерновую или овсяную для увеличения клетчатки",
      "Масло → использовать спрей или минимизировать количество при жарке",
      "Соль → травяная смесь без натрия",
      "Шаг 3. Как замесить идеальное тесто для оладьев из кабачков?",
      "Добавьте в кабачки яйцо и соль, перемешайте. Порциями начинайте всыпать просеянную муку, сразу размешивая ее. Должно получиться тесто, напоминающее густую сметану.",
      "Как влажность муки влияет на количество жидкости в тесте?",
      "Самым прямым образом: более влажная мука потребует меньше жидкости, а сухая — наоборот, больше. Поэтому опытные хозяйки всегда ориентируются на консистенцию, а не на \"сухие\" граммы. Учитывайте, что муки может понадобиться чуть больше или меньше. Этому подходу обучают в базовом уроке Академии — присоединяйтесь!",
      "Секреты шеф-повара",
      "Двойная пышность: добавьте в тесто щепотку разрыхлителя — он сделает оладьи более пышными и воздушными, даже без длительного выстаивания.",
      "Хрустящая корочка: добавьте в тесто столовую ложку кукурузного крахмала или манной крупы — они впитывают лишнюю влагу и делают оладьи более хрустящими снаружи.",
      "Чесночный акцент: добавьте в тесто мелко рубленый чеснок (1 зубчик) или сушёный чесночный порошок — он придаст оладьям пикантный аромат и сделает их более интересными на вкус.",
      "Зелень для свежести: вмешайте в тесто мелко рубленый укроп или петрушку — они добавят свежий аромат и красивые зелёные вкрапления, которые сделают оладьи наряднее.",
      "Сырная стружка: добавьте в тесто горсть натёртого твёрдого сыра (пармезан, чеддер) — он расплавится при жарке и создаст хрустящую сырную корочку, которая преобразит привычные оладьи.",
      "Шаг 4. Как пожарить кабачковые оладьи?",
      "На сковороде разогрейте растительное масло. Выложите тесто, формируя оладьи. Жарьте с одной стороны до золотистой корочки примерно 2-3 минуты, переверните. Жарьте с другой стороны до готовности.",
      "Как выбрать идеальную сковороду для разных блюд?",
      "Материал, из которого изготовлена сковорода, играет ключевую роль. Чтобы разобраться, загляните в статью Кулинарной Академии.",
      "Какое масло самое универсальное для жарки?",
      "Если нужно одно масло на все случаи жизни, берите рафинированное подсолнечное или рафинированное кукурузное. У них нейтральный вкус, высокая термостойкость, и они есть в любом магазине. А если хотите научиться подбирать масло к каждому блюду, то полный гид с таблицами и советами вас ждёт в этом уроке Академии — загляните.",
      "Шаг 5. Как подавать кабачковые оладьи?",
      "Подавайте оладьи, дополнив их натуральным йогуртом или сметаной.",
      "Как хранить кабачковые оладьи?",
      "Готовые оладьи храните в герметичном контейнере в холодильнике до 1-2 дней. При разогреве используйте сковороду или духовку — так корочка снова станет хрустящей. Не замораживайте — кабачки потеряют текстуру, оладьи станут резиновыми.",
      "Секреты шеф-повара",
      "Соус-дополнение: подавайте оладьи с соусом из сметаны, чеснока и мелко рубленого укропа — этот соус идеально подчёркивает нежный вкус кабачков и добавляет свежий акцент.",
      "Праздничная подача: выложите оладьи горкой на блюдо, украсьте зеленью и дольками свежих помидоров черри — яркая и аппетитная закуска для любого стола.",
      "Обеденная тарелка: подавайте оладьи как гарнир к мясу или рыбе, или как самостоятельное блюдо с лёгким овощным салатом.",
      "Смотреть видео приготовления"
    ])
  end

  it "keeps every ingredient in one unnamed group" do
    expect(recipe.ingredient_groups.map(&:to_h)).
      to eq([{ purpose: nil, ingredients: recipe.ingredients, parsed_ingredients: recipe.parsed_ingredients }])
  end

  it "joins the steps into the instructions text" do
    expect(recipe.instructions).to eq("Шаг 1. Как сделать кабачковые оладьи на сковороде?\nПодготовьте продукты. Кабачки вымойте.\nЗамена ингредиентов\nКабачки → цуккини, патиссоны, тыква (молодая)\nПшеничная мука → цельнозерновая, овсяная, кукурузная, безглютеновая смесь\nЯйца → перепелиные (увеличить количество в 3 раза)\nСоль → морская, гималайская, травяная смесь\nРастительное масло → оливковое, подсолнечное рафинированное, масло авокадо\nСовет\nДля оладий выбирайте молодые кабачки с тонкой кожицей и мелкими семенами. Если используете старые кабачки, очистите их и удалите семена.\nШаг 2. Как правильно подготовить кабачки?\nНатрите кабачок на крупной терке. Отожмите получившуюся массу. Сок слейте.\nКак выбрать универсальную тёрку?\nИщите четырёхгранную тёрку из нержавеющей стали с удобной ручкой и резиновыми ножками. Обязательно наличие всех четырёх типов отверстий: крупные и мелкие капли (для сыра, овощей), пятиугольники (для цедры, имбиря) и продолговатые (для нарезки колечками). Чек-лист по выбору идеальной тёрки — в гиде Кулинарной Академии.\nСоветы\nПосыпьте натёртые кабачки солью и оставьте на 10-15 минут, затем отожмите — соль вытянет максимум влаги, и оладьи будут особенно хрустящими и не разваливаться при жарке.\nСбрызните натёртые кабачки лимонным соком перед отжимом — кислинка сохранит их цвет и добавит лёгкую свежую ноту.\nДиетические адаптации\nМука → заменить на цельнозерновую или овсяную для увеличения клетчатки\nМасло → использовать спрей или минимизировать количество при жарке\nСоль → травяная смесь без натрия\nШаг 3. Как замесить идеальное тесто для оладьев из кабачков?\nДобавьте в кабачки яйцо и соль, перемешайте. Порциями начинайте всыпать просеянную муку, сразу размешивая ее. Должно получиться тесто, напоминающее густую сметану.\nКак влажность муки влияет на количество жидкости в тесте?\nСамым прямым образом: более влажная мука потребует меньше жидкости, а сухая — наоборот, больше. Поэтому опытные хозяйки всегда ориентируются на консистенцию, а не на \"сухие\" граммы. Учитывайте, что муки может понадобиться чуть больше или меньше. Этому подходу обучают в базовом уроке Академии — присоединяйтесь!\nСекреты шеф-повара\nДвойная пышность: добавьте в тесто щепотку разрыхлителя — он сделает оладьи более пышными и воздушными, даже без длительного выстаивания.\nХрустящая корочка: добавьте в тесто столовую ложку кукурузного крахмала или манной крупы — они впитывают лишнюю влагу и делают оладьи более хрустящими снаружи.\nЧесночный акцент: добавьте в тесто мелко рубленый чеснок (1 зубчик) или сушёный чесночный порошок — он придаст оладьям пикантный аромат и сделает их более интересными на вкус.\nЗелень для свежести: вмешайте в тесто мелко рубленый укроп или петрушку — они добавят свежий аромат и красивые зелёные вкрапления, которые сделают оладьи наряднее.\nСырная стружка: добавьте в тесто горсть натёртого твёрдого сыра (пармезан, чеддер) — он расплавится при жарке и создаст хрустящую сырную корочку, которая преобразит привычные оладьи.\nШаг 4. Как пожарить кабачковые оладьи?\nНа сковороде разогрейте растительное масло. Выложите тесто, формируя оладьи. Жарьте с одной стороны до золотистой корочки примерно 2-3 минуты, переверните. Жарьте с другой стороны до готовности.\nКак выбрать идеальную сковороду для разных блюд?\nМатериал, из которого изготовлена сковорода, играет ключевую роль. Чтобы разобраться, загляните в статью Кулинарной Академии.\nКакое масло самое универсальное для жарки?\nЕсли нужно одно масло на все случаи жизни, берите рафинированное подсолнечное или рафинированное кукурузное. У них нейтральный вкус, высокая термостойкость, и они есть в любом магазине. А если хотите научиться подбирать масло к каждому блюду, то полный гид с таблицами и советами вас ждёт в этом уроке Академии — загляните.\nШаг 5. Как подавать кабачковые оладьи?\nПодавайте оладьи, дополнив их натуральным йогуртом или сметаной.\nКак хранить кабачковые оладьи?\nГотовые оладьи храните в герметичном контейнере в холодильнике до 1-2 дней. При разогреве используйте сковороду или духовку — так корочка снова станет хрустящей. Не замораживайте — кабачки потеряют текстуру, оладьи станут резиновыми.\nСекреты шеф-повара\nСоус-дополнение: подавайте оладьи с соусом из сметаны, чеснока и мелко рубленого укропа — этот соус идеально подчёркивает нежный вкус кабачков и добавляет свежий акцент.\nПраздничная подача: выложите оладьи горкой на блюдо, украсьте зеленью и дольками свежих помидоров черри — яркая и аппетитная закуска для любого стола.\nОбеденная тарелка: подавайте оладьи как гарнир к мясу или рыбе, или как самостоятельное блюдо с лёгким овощным салатом.\nСмотреть видео приготовления")
  end

  it "reads the recipe metadata", :aggregate_failures do
    expect(recipe.host).to eq("1000.menu")
    expect(recipe.canonical_url).to eq("https://1000.menu/cooking/41421-kabachkovye-oladi-iz-kabachkov-na-skovorode")
    expect(recipe.site_name).to be_nil
    expect(recipe.language).to eq("ru")
    expect(recipe.author).to eq("katushafin")
    expect(recipe.description).to eq("Меньше влаги — секрет золотистой корочки.")
    expect(recipe.image).to eq("https://static.1000.menu/res/380/img/content-v2/04/8a/41421/kabachkovye-oladi-iz-kabachkov-na-skovorode_1758612266_0_2nmqite_max.jpg")
    expect(recipe.category).to be_nil
    expect(recipe.cuisine).to be_nil
    expect(recipe.cooking_method).to be_nil
    expect(recipe.yields).to eq("4 servings")
    expect(recipe.total_time).to eq(30)
    expect(recipe.prep_time).to be_nil
    expect(recipe.cook_time).to be_nil
    expect(recipe.keywords).to be_nil
    expect(recipe.equipment).to be_nil
    expect(recipe.dietary_restrictions).to be_nil
    expect(recipe.ratings).to eq(5.0)
    expect(recipe.ratings_count).to eq(442)
  end

  it "reads the nutrients" do
    expect(recipe.nutrients).to eq({ "calories" => "91" })
  end

  it "parses every nutrient into a name, a unit and an amount" do
    expect(recipe.parsed_nutrients.map(&:to_h)).to eq([
      { name: "calories", unit: nil, amount: 91.0 }
    ])
  end

  it "collects the links on the page" do
    expect(recipe.links).to include("#")
  end
end
